def num_squares(n):
    def f(a):                  # fewest squares summing to a
        if a == 0:
            return 0
        best = inf
        k = 1
        while k * k <= a:
            best = min(best, 1 + f(a - k * k))
            k += 1
        return best
    return f(n)

