def num_squares(n):
    squares = [k * k for k in range(1, isqrt(n) + 1)]
    dp = [0] + [inf] * n
    for a in range(1, n + 1):
        for s in squares:
            if s > a:
                break
            if dp[a - s] + 1 < dp[a]:
                dp[a] = dp[a - s] + 1
    return dp[n]

def num_squares(n):
    if isqrt(n) ** 2 == n:
        return 1
    for a in range(1, isqrt(n) + 1):
        rest = n - a * a
        if isqrt(rest) ** 2 == rest:
            return 2
    m = n
    while m % 4 == 0:
        m //= 4
    return 4 if m % 8 == 7 else 3
